import numpy as np
from scipy import stats

MAX_DRIVERS = 4

def design(feats):
    # Remove near-duplicates (correlated pairs with |r| >= 0.6)
    correlated_pairs = {
        ('ZRVA4L', 'TAI1A'), ('VQA3B', 'KIMC5A'), ('TNH5', 'SWXV11P'),
        ('FWC14', 'OXMA10'), ('FLB7', 'SWXV11P'), ('OXMA10', 'IQI6P'),
        ('VQA3B', 'TIAD13A'), ('VQA3B', 'TMB1'), ('FWC14', 'IQI6P'),
        ('KIMC5A', 'TIAD13A'), ('TNH5', 'FLB7'), ('FWC14', 'VQA3B'),
        ('BPL10L', 'SDG19'), ('XLDI17', 'VQA3B'), ('AOUQ14', 'NBPK12'),
        ('HQG1', 'GASL1A'), ('TNH5', 'VQA3B'), ('AIH18L', 'VQA3B'),
        ('VQA3B', 'JFEA2P'), ('KIMC5A', 'TMB1')
    }

    # Keep one feature from each correlated pair
    keep_ids = set(feats.ids)
    for a, b in correlated_pairs:
        if a in keep_ids and b in keep_ids:
            # Prefer the one with higher absolute t-statistic
            ta = abs(stats.ttest_ind(feats.x[:, feats.column(a)][feats.y==1], 
                                   feats.x[:, feats.column(a)][feats.y==0]).statistic)
            tb = abs(stats.ttest_ind(feats.x[:, feats.column(b)][feats.y==1], 
                                   feats.x[:, feats.column(b)][feats.y==0]).statistic)
            if ta >= tb:
                keep_ids.remove(b)
            else:
                keep_ids.remove(a)

    # Filter to non-correlated features
    filtered_ids = tuple(id for id in feats.ids if id in keep_ids)
    filtered_x = feats.x[:, [feats.column(id) for id in filtered_ids]]

    if len(filtered_ids) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Calculate effect sizes (mean difference between groups)
    effect_sizes = []
    for i, fid in enumerate(filtered_ids):
        y0_mean = np.mean(filtered_x[feats.y==0, i])
        y1_mean = np.mean(filtered_x[feats.y==1, i])
        effect_size = abs(y1_mean - y0_mean)
        effect_sizes.append(effect_size)

    # Select top candidates based on effect size
    candidate_indices = np.argsort(effect_sizes)[::-1][:min(5, len(filtered_ids))]

    # For each candidate, check if it's significantly associated
    significant_features = []
    for i in candidate_indices:
        fid = filtered_ids[i]
        # Welch's t-test
        t_stat, p_val = stats.ttest_ind(
            filtered_x[feats.y==1, i], 
            filtered_x[feats.y==0, i]
        )
        if abs(t_stat) > 2.0 and p_val < 0.05:
            significant_features.append((i, fid))

    if not significant_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Limit to MAX_DRIVERS maximum
    selected_indices = [idx for idx, _ in significant_features[:MAX_DRIVERS]]
    selected_ids = [fid for _, fid in significant_features[:MAX_DRIVERS]]

    # Simple weighted score approach: use top feature as main driver
    if selected_ids:
        # Weight by effect size (but normalize)
        weights = {}
        for i, fid in enumerate(selected_ids):
            y0_mean = np.mean(filtered_x[feats.y==0, selected_indices[i]])
            y1_mean = np.mean(filtered_x[feats.y==1, selected_indices[i]])
            weights[fid] = abs(y1_mean - y0_mean)

        # Normalize weights
        total_weight = sum(weights.values())
        if total_weight > 0:
            weights = {k: v/total_weight for k, v in weights.items()}

        # Only include top 3 features in products to keep model small
        products = []
        for i in range(min(3, len(selected_indices))):
            for j in range(i+1, min(3, len(selected_indices))):
                products.append((selected_ids[i], selected_ids[j]))

        return Design(
            drivers=tuple(selected_ids),
            columns=filtered_ids,
            products=tuple(products),
            loadings=weights
        )

    # If no features meet criteria, return empty design
    return Design(drivers=(), columns=(), products=(), loadings={})
